import functools

def logger(func):
    @functools.wraps(func)
    def wrapper():
        print("before")
        func()
        print("after")
    return wrapper

@logger
def hello():
    print("hello")

hello()
print(hello.__name__)

def deco(func):
    def inner():
        return func()
    return inner

def report():
    return "ok"

plain_name = report.__name__
report = deco(report)
print(plain_name)
print(report.__name__)
print(report())

def repeat(times):
    def deco(func):
        def wrapper():
            for _ in range(times):
                func()
        return wrapper
    return deco

@repeat(2)
def greet():
    print("hi")

greet()

