class Counter:
    def __init__(self, func):
        self.func = func
        self.calls = 0
    def __call__(self):
        self.calls += 1
        return self.func()
    def show(self):
        return self.calls

@Counter
def run():
    return "run"

print(run())
print(run())
print(run.show())

def add_repr(cls):
    cls.describe = lambda self: f"instance of {type(self).__name__}"
    return cls

@add_repr
class Dog:
    def speak(self):
        return "woof"

d = Dog()
print(d.speak())
print(d.describe())

def trace(func):
    def wrapper(self, *args, **kwargs):
        print("call", func.__name__)
        return func(self, *args, **kwargs)
    return wrapper

class Calc:
    def __init__(self, base):
        self.base = base
    @trace
    def add(self, x):
        return self.base + x

c = Calc(10)
print(c.add(5))

import functools

calls = []

@functools.lru_cache(maxsize=None)
def fib(n):
    calls.append(n)
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(10))
print(len(calls))

