import functools

def log(*args, **kwargs):
    if len(args) == 1 and callable(args[0]) and not kwargs:
        return log()(args[0])
    prefix = args[0] if args else "LOG"
    def deco(func):
        @functools.wraps(func)
        def wrapper():
            result = func()
            print(f"{prefix}:{result}")
            return result
        return wrapper
    return deco

@log
def a():
    return "a"

@log("X")
def b():
    return "b"

print(a())
print(b())

class CountCalls:
    def __init__(self, func):
        self.func = func
        self.count = 0
    def __call__(self, *args, **kwargs):
        self.count += 1
        return self.func(*args, **kwargs)

@CountCalls
def power(base, exp):
    return base ** exp

print(power(2, 3))
print(power(3, 2))
print(power.count)

