class Temperature:
    def __init__(self, celsius):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        self._celsius = value

    @property
    def fahrenheit(self):
        return self._celsius * 9 / 5 + 32

t = Temperature(25)
print(t.fahrenheit)
t.celsius = 0
print(t.fahrenheit)

import functools

attempts = []

def retry(times):
    def deco(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(times):
                attempts.append(i)
                result = func(*args, **kwargs)
                if result == "ok":
                    return result
            return "failed"
        return wrapper
    return deco

@retry(3)
def unstable():
    if len(attempts) < 2:
        return "again"
    return "ok"

print(unstable())
print(len(attempts))
